using Microsoft.AspNetCore.Mvc; using MovieTicketBooking.Web.Services; using MovieTicketBooking.Web.Models;
namespace MovieTicketBooking.Web.Controllers;
public class BookingController:Controller { readonly MovieStore s; readonly TmdbService tmdb; public BookingController(MovieStore s,TmdbService tmdb){this.s=s;this.tmdb=tmdb;} public async Task<IActionResult> Tmdb(int id){var m=await tmdb.DetailsAsync(id);if(m==null)return NotFound();var local=new Movie{MovieID="TMDB-"+m.Id,MovieName=m.Title,Duration=m.Runtime>0?m.Runtime/60.0:2.0,Genre=m.GenresText,Language="English",Story=m.Overview,PosterUrl=m.PosterUrl};var ensured=s.EnsureTmdbMovie(local);var first=ensured.Shows.FirstOrDefault();return first==null?NotFound():RedirectToAction("Select",new{id=first.ShowID});}
 public IActionResult Select(int id){var show=s.Show(id);if(show==null)return NotFound();var theatre=s.Theatre(show.TheatreID)!;var movie=s.Movie(show.MovieID)!;ViewBag.Occupied=s.Occupied(id);return View(new BookingVm{ShowCard=new ShowCard{Show=show,Theatre=theatre,Movie=movie,AvailableSeats=theatre.NumberOfSeats-s.Occupied(id).Count()}});} [HttpPost] public IActionResult Confirm(int showId,string seatType,string selectedSeats){var cid=HttpContext.Session.GetInt32("CustomerId");if(cid==null)return RedirectToAction("Login","Account",new { returnUrl = $"/Booking/Select?id={showId}" });var c=s.Customers.FirstOrDefault(x=>x.CustomerID==cid);var show=s.Show(showId);if(c==null||show==null)return RedirectToAction("Login","Account");var theatre=s.Theatre(show.TheatreID);if(theatre==null){TempData["Error"]="Theatre information could not be found.";return RedirectToAction("Select",new{id=showId});}if(string.IsNullOrWhiteSpace(selectedSeats)){TempData["Error"]="Please select at least one seat.";return RedirectToAction("Select",new{id=showId});}var seats=selectedSeats.Split(',',StringSplitOptions.RemoveEmptyEntries).Select(x=>int.TryParse(x,out var n)?(int?)n:null).Where(x=>x.HasValue).Select(x=>x!.Value).Distinct().Order().ToList();if(seats.Count<1||seats.Count>6){TempData["Error"]="Select between 1 and 6 seats.";return RedirectToAction("Select",new{id=showId});}var occupied=s.Occupied(showId);if(seats.Any(x=>x<1||x>theatre.NumberOfSeats||occupied.Contains(x))){TempData["Error"]="One or more selected seats are unavailable.";return RedirectToAction("Select",new{id=showId});}decimal rate=seatType switch{"Platinum"=>show.PlatinumSeatRate,"Silver"=>show.SilverSeatRate,_=>show.GoldSeatRate};var b=new Booking{BookingID=Enumerable.Range(10000,100000).First(x=>!s.Bookings.Any(y=>y.BookingID==x)),BookingDate=DateTime.Now,ShowID=showId,CustomerID=c.CustomerID,CustomerName=c.CustomerName,Email=c.Email,SeatNumbers=seats,SeatType=seatType,Amount=rate*seats.Count};s.Bookings.Add(b);s.Save();return RedirectToAction("Confirmation",new{id=b.BookingID});} public IActionResult Confirmation(int id){var b=s.Bookings.FirstOrDefault(x=>x.BookingID==id);if(b==null)return NotFound();ViewBag.Show=s.Show(b.ShowID);ViewBag.Movie=s.Movie(s.Show(b.ShowID)!.MovieID);ViewBag.Theatre=s.Theatre(s.Show(b.ShowID)!.TheatreID);return View(b);} public IActionResult Mine(){var id=HttpContext.Session.GetInt32("CustomerId");if(id==null)return RedirectToAction("Login","Account");ViewBag.Bookings=s.Bookings.Where(x=>x.CustomerID==id).OrderByDescending(x=>x.BookingDate).ToList();return View();} [HttpPost] public IActionResult Cancel(int id){var b=s.Bookings.FirstOrDefault(x=>x.BookingID==id);if(b!=null&&b.CustomerID==HttpContext.Session.GetInt32("CustomerId")){b.BookingStatus="Cancelled";s.Save();}return RedirectToAction("Mine");} }
